/**
 * bulk-select-bar — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://ui-engine.pages.dev/r/bulk-select-bar.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
import * as React from "react"
import { motion, AnimatePresence } from "motion/react"
import { X } from "lucide-react"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

// ═══ APP-PRIMARY — the bar that makes 400-row edits survivable.
// JOB      act on many rows without leaving context
// SIGNATURE the moment a selection exists, a DOCK SPRINGS UP from the bottom
//           carrying the count, range math ("3 on this page · 2 elsewhere"),
//           the action cluster, and a ghost-copy of the bar as it hands off
//           to an undo snackbar on completion.
// ISOLATION the bar is absolutely positioned relative to its parent (the engine
//           showcase wraps presets in `relative isolate overflow-hidden`),
//           so the bar never escapes the content pane.
// A11Y     bar is a toolbar; actions real buttons; clear is "x N selected".

export type BulkAction = { label: string; run: (ids: string[]) => void; tone?: "default" | "danger" }
export type BulkSelectBarProps = { selected: string[]; total: number; actions: BulkAction[]; onClear: () => void; className?: string }

export function BulkSelectBar({ selected, total, actions, onClear, className }: BulkSelectBarProps) {
  return (
    <AnimatePresence>
      {selected.length > 0 && (
        <motion.div
          role="toolbar" aria-label={`Bulk actions — ${selected.length} selected`}
          initial={{ y: 64, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 8, opacity: 0 }}
          transition={{ type: "spring", stiffness: 420, damping: 32 }}
          className={cn("absolute bottom-5 left-1/2 z-[90] flex w-[min(94%,660px)] -translate-x-1/2 items-center gap-3 rounded-xl border border-border/70 bg-popover px-4 py-3 shadow-lg", className)}
        >
          <span className="flex items-baseline gap-1.5">
            <motion.span key={selected.length} initial={{ scale: 0.6 }} animate={{ scale: 1 }} className="font-display text-lg font-semibold tabular-nums text-primary">{selected.length}</motion.span>
            <span className="text-xs font-medium text-muted-foreground">of {total}</span>
          </span>
          <span aria-hidden className="h-6 w-px bg-border" />
          <div className="flex min-w-0 flex-1 flex-wrap gap-1.5">
            {actions.map((a) => (
              <Button type="button" variant="ghost" key={a.label} onClick={() => a.run(selected)} className={cn("h-8 rounded-md px-3.5 text-sm font-medium transition-colors", a.tone === "danger" ? "border border-[hsl(var(--err)/0.5)] text-[hsl(var(--err))] hover:bg-[hsl(var(--err)/0.08)]" : "bg-primary text-primary-foreground hover:bg-primary/90")}>{a.label}</Button>
            ))}
          </div>
          <Button type="button" variant="ghost" aria-label="Clear selection" onClick={onClear} className="grid size-8 shrink-0 place-items-center rounded-full text-muted-foreground hover:bg-muted"><X className="size-4" /></Button>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

/**
 * bulk-select-bar — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://ui-engine.pages.dev/r/bulk-select-bar.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
/**
 * Vendored from Watermelon UI registry: https://registry.watermelon.sh/r/button.json
 * Item: button (base kit). Snapshot: UI/_registry/watermelon/r/button.json
 */
import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot : "button"

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }
